fn prepaint(
    &mut self,
    line_height: Pixels,
    scroll_position: gpui::Point<ScrollOffset>,
    scroll_pixel_position: gpui::Point<ScrollPixelOffset>,
    row: DisplayRow,
    content_origin: gpui::Point<Pixels>,
    line_elements: &mut SmallVec<[AnyElement; 1]>,
    window: &mut Window,
    cx: &mut App,
) {
    let line_y = f32::from(line_height) * Pixels::from(row.as_f64() - scroll_position.y);
    self.prepaint_with_custom_offset(
        line_height,
        scroll_pixel_position,
        content_origin,
        line_y,
        line_elements,
        window,
        cx,
    );
}

fn prepaint_with_custom_offset(
    &mut self,
    line_height: Pixels,
    scroll_pixel_position: gpui::Point<ScrollPixelOffset>,
    content_origin: gpui::Point<Pixels>,
    line_y: Pixels,
    line_elements: &mut SmallVec<[AnyElement; 1]>,
    window: &mut Window,
    cx: &mut App,
) {
    let mut fragment_origin =
        content_origin + gpui::point(Pixels::from(-scroll_pixel_position.x), line_y);
    for fragment in &mut self.fragments {
        match fragment {
            LineFragment::Text(line) => {
                fragment_origin.x += line.width;
            }
            LineFragment::Element { element, size, .. } => {
                let mut element = element
                    .take()
                    .expect("you can't prepaint LineWithInvisibles twice");

                // Center the element vertically within the line.
                let mut element_origin = fragment_origin;
                element_origin.y += (line_height - size.height) / 2.;
                element.prepaint_at(element_origin, window, cx);
                line_elements.push(element);

                fragment_origin.x += size.width;
            }
        }
    }
}

fn draw(
    &self,
    layout: &EditorLayout,
    row: DisplayRow,
    content_origin: gpui::Point<Pixels>,
    whitespace_setting: ShowWhitespaceSetting,
    selection_ranges: &[Range<DisplayPoint>],
    window: &mut Window,
    cx: &mut App,
) {
    self.draw_with_custom_offset(
        layout,
        row,
        content_origin,
        layout.position_map.line_height
            * (row.as_f64() - layout.position_map.scroll_position.y) as f32,
        whitespace_setting,
        selection_ranges,
        window,
        cx,
    );
}

