fn layout_blame_entries(
    &self,
    buffer_rows: &[RowInfo],
    em_width: Pixels,
    scroll_position: gpui::Point<ScrollOffset>,
    start_row: DisplayRow,
    line_height: Pixels,
    gutter_hitbox: &Hitbox,
    max_width: Option<Pixels>,
    window: &mut Window,
    cx: &mut App,
) -> Option<Vec<AnyElement>> {
    if !self
        .editor
        .update(cx, |editor, cx| editor.render_git_blame_gutter(cx))
    {
        return None;
    }

    let blame = self.editor.read(cx).blame.clone()?;
    let workspace = self.editor.read(cx).workspace()?;
    let blamed_rows: Vec<_> = blame.update(cx, |blame, cx| {
        blame.blame_for_rows(buffer_rows, cx).collect()
    });

    let width = if let Some(max_width) = max_width {
        AvailableSpace::Definite(max_width)
    } else {
        AvailableSpace::MaxContent
    };
    let start_x = em_width;

    let mut last_used_color: Option<(Hsla, Oid)> = None;
    let blame_renderer = cx.global::<GlobalBlameRenderer>().0.clone();

    let shaped_lines = blamed_rows
        .into_iter()
        .enumerate()
        .flat_map(|(ix, blame_entry)| {
            let (buffer_id, blame_entry) = blame_entry?;
            let mut element = render_blame_entry(
                ix,
                &blame,
                blame_entry,
                &self.style,
                &mut last_used_color,
                self.editor.clone(),
                workspace.clone(),
                buffer_id,
                &*blame_renderer,
                window,
                cx,
            )?;

            let start_y = line_height
                * (DisplayRow(start_row.0 + ix as u32).as_f64() - scroll_position.y) as f32;
            let absolute_offset = gutter_hitbox.origin + point(start_x, start_y);

            element.prepaint_as_root(
                absolute_offset,
                size(width, AvailableSpace::MinContent),
                window,
                cx,
            );

            Some(element)
        })
        .collect();

    Some(shaped_lines)
}

