    ...
    let width = match EditorSettings::get_global(cx).gutter.git_gutter_width {
        GitGutterWidth::Custom(width) => px(*width),
        GitGutterWidth::Default => (0.35 * line_height).floor(),
    };
```

对比旧代码(提交 a7d74150ac 之前):

```rust
